SELECT COUNT(*) FROM screening
WHERE hall_id = #{hallId} AND status != 3
  AND id != #{excludedId}
  AND start_time < #{occupiedEnd}
  AND TIMESTAMPDIFF(SECOND, #{start}, end_time) + turnaround_minutes_snapshot * 60 > 0

mapper.update:
UPDATE screening SET status = #{to}, version = version + 1, update_time = UTC_TIMESTAMP()
, sale_start_time = #{saleStart}
WHERE id = #{id} AND version = #{version} AND status = #{from}

    AND sale_end_time > #{now} AND end_time > #{now}
    AND end_time <= #{now}
    AND end_time > #{now}
